#!/usr/bin/env bash
# init_flags.sh — generate per-build opaque flag token for hvac-lab
# (runtime-only, not committed in source). Mirrors network-chain
# flags/init_flags.sh. Writes a .env the compose stack reads.
# Run once before `docker compose up`. Re-run to rotate.
set -euo pipefail
cd "$(dirname "$0")/.."

rand() { head -c 16 /dev/urandom | od -An -tx1 | tr -d ' \n'; }

FLAG="CTF{hvac_maintenance_report_mid_$(rand)}"

cat > .env <<EOF
# generated by flags/init_flags.sh — do not commit
HVAC_FLAG=${FLAG}
HVAC_RUN_DIR=/var/run/hvac
EOF

echo "wrote .env with fresh HVAC flag."
echo "  mid (maintenance report): ${FLAG}"
echo "SSH entry stays static (predictable-password vuln):"
echo "  ssh default@localhost -p 2223  # password: HVAC-1001-STAT"
echo "  (then predict engineer password HVAC-1002-STAT and: su engineer)"
